    private static void c1(ModConfigSpec.Builder b) {
        b.comment("Reinforcement System \n When a parasite is killed, there is a chance for it to call reinforcements, this means that\n a Beckon will spawn nearby and will help in the fight.\n \n The Beckon has different stages and that will tell how many and which parasites it will spawn.");
        b.push(List.of("reinforcement_system"));
        b.comment("Set to false if you want to disable the Reinforcement System.");
        k13 = b.define(List.of("Reinforcement System Enabled"), true);
        b.comment("Chance (1 = 100%) to spawn a Beckon (This is ignored if Evolution Phases are enabled, it has its own option).");
        k14 = b.defineInRange(List.of("Reinforcement System Chance"), 0.07, 0.0, 1.0);
        b.comment("Set to false if you want to disable the Reinforcement System Sounds \n (A bell sound is played when a Beckon is summoned or when it grew up to the next stage).");
        k15 = b.define(List.of("Reinforcement System Sounds"), true);
        b.comment("Set to false if you want to disable the Reinforcement System Block Infestation.");
        k16 = b.define(List.of("Reinforcement System Infestation"), true);
        b.comment("Max Hardness of the block it can infest.");
        k17 = b.defineInRange(List.of("Reinforcement System Hardness"), 4.5, 0.01, 100.0);
        b.comment("Set to true if you want the Reinforcement System to only be activated by the Players.");
        k18 = b.define(List.of("Reinforcement System Player Only"), false);
        b.comment("List of block that can't be infested, Ex: \"minecraft:stonebrick\" or just \"minecraft\" for a whole mod");
        k19 = b.defineListAllowEmpty(List.of("Reinforcement System Blocks BlackList"), List.of(), () -> "", o -> o instanceof String);
        b.comment("Set to true if you want to use the list as a WhiteList.");
        k20 = b.define(List.of("Reinforcement System Blocks BlackList Inverted"), false);
        b.comment("What the infested block turns into when the Beckons die, meta value important");
        k21 = b.define(List.of("Reinforcement System Revert Block"), "minecraft:gravel:0");
        b.comment("What the infested block 2 turns into when the Beckons die, meta value important");
        k22 = b.define(List.of("Reinforcement System Revert Block 2"), "minecraft:mossy_cobblestone:0");
        b.comment("If the light level is higher than this, the block will not spread.");
        k23 = b.defineInRange(List.of("Reinforcement System Block Light Level"), 16, 0, 16);
        b.comment("One in X to spawn a Beckon on the Infested Block Residue (random tick) (This value is ignored if Evolution Phases are enabled, it has its own option).");
        k24 = b.defineInRange(List.of("Reinforcement System Block Residue Chance"), 5000, 0, 2147483640);
        b.comment("Chance (1 = 100%) to spawn spore particle in an infested block (if available, every tick).");
        k25 = b.defineInRange(List.of("Reinforcement System Particle Spore Chance"), 0.05, 0.0, 1.0);
        b.comment("Chance (1 = 100%) to spawn fog particle in an infested block ((if available, every tick).");
        k26 = b.defineInRange(List.of("Reinforcement System Particle Fog Chance"), 0.05, 0.0, 1.0);
        b.comment("Cooldown (in seconds) for the Reinforcement System spawning Beckons.");
        k27 = b.defineInRange(List.of("Reinforcement System Cooldown"), 2, 1, 2147483640);
        b.comment("Maximum Stage a Beckon can grow up in a Dimension. Ex. \"1;3\"  Where: \n \"1\" is for the dimension, \n \"3\" is for the stage it cannot grow up. \n");
        k28 = b.defineListAllowEmpty(List.of("Reinforcement System Maximum Stage"), List.of("1;3"), () -> "", o -> o instanceof String);
        b.comment("Set to false if you don't want the Beckons to ignore their summoning cooldown.when spawning.");
        k29 = b.define(List.of("Reinforcement System Ignore Cooldown"), true);
        b.comment("Set to true if you want Beckons to only spawn if the position can see the sky (only those who are called by the death of a parasite).");
        k30 = b.define(List.of("Reinforcement System Sky"), false);
        b.comment("Set to true if you want Beckons to only spawn if the position can see the sky (from residue blocks).");
        k31 = b.define(List.of("Reinforcement System Sky Residue"), false);
        b.comment("If the y value of the block is below this, Beckons will not spawn from it.");
        k32 = b.defineInRange(List.of("Reinforcement System Block Residue Y"), 0, 0, 300);
        b.comment("Chance (1 = 100%) to spawn a Beckon in Infested Blocks (S!=1) if no Beckon is around, to further infest the land.");
        k33 = b.defineInRange(List.of("Reinforcement System Infestation Spawning Beckons"), 0.05, 0.0, 1.0);
        b.comment("If a Beckon is killed on an Infested block, the block will start a chain reaction and revert back all connected blocks if the meta of the block is less than or equal to this value AND the stage of the Beckon is greater than or equal to the meta value .");
        k34 = b.defineInRange(List.of("Reinforcement System Block Revert Stage"), 1, 1, 3);
        b.pop();
    }
    private static void c2(ModConfigSpec.Builder b) {
        b.comment("Merge System \n The Assimilated have the ability to learn from their battles and if the conditions are met, they will \n start to melt until they're some Moving Flesh \n If 2 of these things meet, they will fuse together and grow, if they get big enough they will spawn \n a mob from the Mob List.\n \n Conditions for the Assimilated to turn into Moving Flesh: \n \n -The first condition: the Assimilated needs to reach the primitive killcount. \n -The second condition: it needs to be next to 3 more Assimilated, regardless of their killcount/specie \n OR it needs to be next to a Moving Flesh. \n If the Assimilated with the killcount is next to atleast 3 more Assimilated, the four of them will start \n to melt BUT if it is next to a Moving flesh, only it will start to melt.");
        b.push(List.of("merge_System"));
        b.comment("Set to false if you don't want to spawn random mobs from the Mob List (values will be used).");
        k35 = b.define(List.of("Merge System Random"), true);
        b.comment("Amount of health (1 = 100%) the mob spawns with.");
        k36 = b.defineInRange(List.of("Merge System Mob Health"), 0.5, 0.0, 1.0);
        b.comment("Mob list used in the merge system to spawn mobs. Ex. \"minecraft:zombie;11\"  Where: \n \"minecraft:zombie\" is for the entity, \n \"11\" is for the value the entity has (value must be an integer). \n Each Assimilated has a value, the value then passes to the Moving Flesh and when 2 Moving Flesh merge together both values will add up\n If the value matches one in the list, the corresponding entity will spawn, else it will be a random one. \n");
        k37 = b.defineListAllowEmpty(List.of("Merge System Mob List"), List.of("srparasites:pri_summoner;0", "srparasites:pri_longarms;0", "srparasites:pri_reeker;0", "srparasites:pri_manducater;0", "srparasites:pri_bolster;0", "srparasites:pri_yelloweye;0", "srparasites:pri_arachnida;0", "srparasites:pri_vermin;0", "srparasites:pri_tozoon;0"), () -> "", o -> o instanceof String);
        b.comment("Assimilated mob list with their values used in the merge system to spawn mobs. Ex. \"srparasites:infhuman;22\"  Where: \n \"srparasites:infhuman\" is for the entity (only works for Assimilated versions minus Big Spider, Enderdragon), \n \"22\" is for the value the Moving Flesh will have (value must be an integer). \n");
        k38 = b.defineListAllowEmpty(List.of("Merge System Assimilated Values"), List.of("srparasites:sim_human;1", "srparasites:sim_cow;1", "srparasites:sim_sheep;1", "srparasites:sim_wolf;1", "srparasites:sim_pig;1", "srparasites:sim_villager;1", "srparasites:sim_enderman;1", "srparasites:sim_bear;2", "srparasites:sim_horse;1"), () -> "", o -> o instanceof String);
        b.pop();
    }
